content:
450          if (colmatch(columns, "ZiZiiCZiiZZOOOOOOOOOOOOOOOOOOOO+")
   451              >= 9 + 2*complete) {
   452              fmt->category = sequence_data;
   453              fmt->format = sam;
   454              fmt->version.major = 1, fmt->version.minor = -1;
   455              return 0;
   456          }
   457          else if (fmt->compression == gzip && colmatch(columns, "iiiiii") == 6) {
   458              fmt->category = index_file;
   459              fmt->format = crai;
   460              return 0;
   461          }
   462          else if (colmatch(columns, "Ziiiii") == 6) {
   463              fmt->category = index_file;
   464              fmt->format = fqi_format;
   465              return 0;
   466          }
   467          else if (colmatch(columns, "Ziiii") == 5) {
   468              fmt->category = index_file;
   469              fmt->format = fai_format;
   470              return 0;
   471          }
   472          else if (colmatch(columns, "Zii+") >= 3) {
   473              fmt->category = region_list;
   474              fmt->format = bed;
   475              return 0;
   476          }
   477      }
   478
   479      // Arbitrary text files can be read using hts_getline().
   480      if (is_text_only(s, &s[len])) fmt->format = text_format;
   481
   482      // Nothing recognised: leave unset fmt-> fields as unknown.
   483      return 0;
