   486  char *hts_format_description(const htsFormat *format)
   487  {
   488      kstring_t str = { 0, 0, NULL };
   489
   490      switch (format->format) {
   491      case sam:   kputs("SAM", &str); break;
   492      case bam:   kputs("BAM", &str); break;
   493      case cram:  kputs("CRAM", &str); break;
   494      case fasta_format:  kputs("FASTA", &str); break;
   495      case fastq_format:  kputs("FASTQ", &str); break;
   496      case vcf:   kputs("VCF", &str); break;
   497      case bcf:
   498          if (format->version.major == 1) kputs("Legacy BCF", &str);
   499          else kputs("BCF", &str);
   500          break;
   501      case bai:   kputs("BAI", &str); break;
   502      case crai:  kputs("CRAI", &str); break;
   503      case csi:   kputs("CSI", &str); break;
   504      case fai_format:    kputs("FASTA-IDX", &str); break;
   505      case fqi_format:    kputs("FASTQ-IDX", &str); break;
   506      case gzi:   kputs("GZI", &str); break;
   507      case tbi:   kputs("Tabix", &str); break;
   508      case bed:   kputs("BED", &str); break;
   509      case htsget: kputs("htsget", &str); break;
   510      case hts_crypt4gh_format: kputs("crypt4gh", &str); break;
   511      case empty_format:  kputs("empty", &str); break;
   512      default:    kputs("unknown", &str); break;
   513      }
   514
   515      if (format->version.major >= 0) {
   516          kputs(" version ", &str);
   517          kputw(format->version.major, &str);
   518          if (format->version.minor >= 0) {
   519              kputc('.', &str);
   520              kputw(format->version.minor, &str);
   521          }
   522      }
   523
   524      switch (format->compression) {
   525      case bzip2_compression:  kputs(" bzip2-compressed", &str); break;
   526      case custom: kputs(" compressed", &str); break;
   527      case gzip:   kputs(" gzip-compressed", &str); break;
   528      case bgzf:
   529          switch (format->format) {
   530          case bam:
   531          case bcf:
   532          case csi:
   533          case tbi:
   534              // These are by definition BGZF, so just use the generic term
   535              kputs(" compressed", &str);
   536              break;
   537          default:
   538              kputs(" BGZF-compressed", &str);
   539              break;
   540          }
