  1041  htsFile *hts_hopen(hFILE *hfile, const char *fn, const char *mode)
  1042  {
  1043      hFILE *hfile_orig = hfile;
  1044      htsFile *fp = (htsFile*)calloc(1, sizeof(htsFile));
  1045      char simple_mode[101], *cp, *opts;
  1046      simple_mode[100] = '\0';
  1047
  1048      if (fp == NULL) goto error;
  1049
  1050      fp->fn = strdup(fn);
  1051      fp->is_be = ed_is_big();
  1052
  1053      // Split mode into simple_mode,opts strings
  1054      if ((cp = strchr(mode, ','))) {
  1055          strncpy(simple_mode, mode, cp-mode <= 100 ? cp-mode : 100);
  1056          simple_mode[cp-mode] = '\0';
  1057          opts = cp+1;
  1058      } else {
  1059          strncpy(simple_mode, mode, 100);
  1060          opts = NULL;
  1061      }
  1062
  1063      if (strchr(simple_mode, 'r')) {
  1064          const int max_loops = 5; // Should be plenty
  1065          int loops = 0;
  1066          if (hts_detect_format(hfile, &fp->format) < 0) goto error;
  1067
  1068          // Deal with formats that re-direct an underlying file via a plug-in.
  1069          // Loops as we may have crypt4gh served via htsget, or
  1070          // crypt4gh-in-crypt4gh.
  1071          while (fp->format.format == htsget ||
  1072                 fp->format.format == hts_crypt4gh_format) {
  1073              // Ensure we don't get stuck in an endless redirect loop
  1074              if (++loops > max_loops) {
  1075                  errno = ELOOP;
  1076                  goto error;
  1077              }
  1078
  1079              if (fp->format.format == htsget) {
  1080                  hFILE *hfile2 = hopen_htsget_redirect(hfile, simple_mode);
  1081                  if (hfile2 == NULL) goto error;
  1082
  1083                  hfile = hfile2;
  1084              }
  1085              else if (fp->format.format == hts_crypt4gh_format) {
  1086                  if (hts_crypt4gh_redirect(fn, simple_mode, &hfile, fp) < 0)
  1087                      goto error;
  1088              }
  1089
  1090              // Re-detect format against the result of the redirection
  1091              if (hts_detect_format(hfile, &fp->format) < 0) goto error;
  1092          }
  1093      }
  1094      else if (strchr(simple_mode, 'w') || strchr(simple_mode, 'a')) {
  1095          htsFormat *fmt = &fp->format;
  1096          fp->is_write = 1;
  1097
  1098          if (strchr(simple_mode, 'b')) fmt->format = binary_format;
  1099          else if (strchr(simple_mode, 'c')) fmt->format = cram;
  1100          else fmt->format = text_format;
  1101
  1102          if (strchr(simple_mode, 'z')) fmt->compression = bgzf;
  1103          else if (strchr(simple_mode, 'g')) fmt->compression = gzip;
  1104          else if (strchr(simple_mode, 'u')) fmt->compression = no_compression;
  1105          else {
  1106              // No compression mode specified, set to the default for the format
  1107              switch (fmt->format) {
  1108              case binary_format: fmt->compression = bgzf; break;
  1109              case cram: fmt->compression = custom; break;
  1110              case text_format: fmt->compression = no_compression; break;
  1111              default: abort();
  1112              }
  1113          }
  1114
  1115          // Fill in category (if determinable; e.g. 'b' could be BAM or BCF)
  1116          fmt->category = format_category(fmt->format);
  1117
  1118          fmt->version.major = fmt->version.minor = -1;
  1119          fmt->compression_level = -1;
  1120          fmt->specific = NULL;
  1121      }
  1122      else { errno = EINVAL; goto error; }
  1123
  1124      switch (fp->format.format) {
  1125      case binary_format:
  1126      case bam:
  1127      case bcf:
  1128          fp->fp.bgzf = bgzf_hopen(hfile, simple_mode);
  1129          if (fp->fp.bgzf == NULL) goto error;
  1130          fp->is_bin = fp->is_bgzf = 1;
  1131          break;
  1132
  1133      case cram:
  1134          fp->fp.cram = cram_dopen(hfile, fn, simple_mode);
  1135          if (fp->fp.cram == NULL) goto error;
  1136          if (!fp->is_write)
  1137              cram_set_option(fp->fp.cram, CRAM_OPT_DECODE_MD, 1);
  1138          fp->is_cram = 1;
  1139          break;
  1140
  1141      case empty_format:
  1142      case text_format:
  1143      case bed:
  1144      case fasta_format:
  1145      case fastq_format:
  1146      case sam:
  1147      case vcf:
  1148          if (fp->format.compression != no_compression) {
  1149              fp->fp.bgzf = bgzf_hopen(hfile, simple_mode);
  1150              if (fp->fp.bgzf == NULL) goto error;
  1151              fp->is_bgzf = 1;
  1152          }
  1153          else
  1154              fp->fp.hfile = hfile;
  1155          break;
