  1331  // as for the underlying type.  Min values are slightly different as
  1332  // the last 8 values for each type were reserved by BCFv2.2.
  1333  #define BCF_MAX_BT_INT8  (0x7f)        /* INT8_MAX  */
  1334  #define BCF_MAX_BT_INT16 (0x7fff)      /* INT16_MAX */
  1335  #define BCF_MAX_BT_INT32 (0x7fffffff)  /* INT32_MAX */
  1336  #define BCF_MIN_BT_INT8  (-120)        /* INT8_MIN  + 8 */
  1337  #define BCF_MIN_BT_INT16 (-32760)      /* INT16_MIN + 8 */
