  1499  static inline int32_t bcf_dec_size(const uint8_t *p, uint8_t **q, int *type)
  1500  {
  1501      *type = *p & 0xf;
  1502      if (*p>>4 != 15) {
  1503          *q = (uint8_t*)p + 1;
  1504          return *p>>4;
  1505      } else return bcf_dec_typed_int1(p + 1, q);
